  asks: [['Could that happen to us?', '“It’s very rare. There are many people working to keep us safe.”']],
  helps: ['Find the helpers together.', 'Keep routines steady.'],
  avoid: ['Leaving news on in the background.'],
  faith: 'Communities often gather to pray and grieve together. Kids can take part in age-right ways.',
