  asks: [['Will it happen again?', '“Fires are rare. We’ll practice our fire plan so we all know what to do.”']],
  helps: ['Replace a comfort item quickly.', 'Practice fire drills at home.'],
  avoid: ['Telling kids not to be sad because "they’re just things."'],
  faith: 'Faith communities often rally around families after disasters, offering help and belonging.',
  after: ['Expect reminders like smoke smells or sirens to bring feelings back.'],
